    }
  },
  "required": [
    "model",
    "state",
    "questions"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "Optional: a specific subagent id. Omit to list all."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
