{
  "type": "object",
  "properties": {
    "to": {
      "type": "string",
      "description": "The sibling subagent id, \"main\", an absolute mailbox \"<sessionId>/main\", a session name from agent_directory, or \"name@machine\" for a cross-machine peer (A2A gateway)."
    },
    "message": {
      "type": "string",
      "description": "The message body for the sibling."
    },
    "report_id": {
      "type": "string",
      "description": "Chunk protocol: the child-selected report id this message is a part of. Same-session recipients only."
    },
    "part_index": {
      "type": "integer",
      "description": "Chunk protocol: the 0-based index of this part. Parts must arrive in order (0, 1, 2, …) without duplicates; the final reply manifest is validated against what the harness observed. Requires report_id."
    },
    "wake": {
      "type": "boolean",
      "description": "When the cross-session target is asleep (no live watcher — it would not read the message until started), launch a detached headless run of its session to process the inbox now. Default: true. The run appends to the same session JSONL, so a later interactive start resumes it."
    }
  },
  "required": [
    "to",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "all": {
      "type": "boolean",
      "description": "Include stale mailboxes (no recent activity, nothing pending). Default: false."
    }
  }
}

{
  "type": "object",
  "properties": {
    "context": {
      "type": "string",
      "description": "Shared background (project state, constraints, contracts) rendered into every spawned subagent's system prompt"
    },
    "tasks": {
      "type": "array",
      "description": "One subagent per item",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Stable id base ([A-Za-z0-9_-]); uniquified per session"
          },
          "agent": {
            "type": "string",
            "description": "Agent type for this item (see the tool description); omit for the general-purpose worker"
          },
          "task": {
            "type": "string",
            "description": "Complete, self-contained instructions for the subagent"
          },
          "outputSchema": {
            "description": "JSON Schema the subagent's final output must satisfy; invalid output gets one fix retry, then the item fails"
          }
        },
        "required": [
          "task"
        ]
      }
    },
    "background": {
      "type": "boolean",
      "description": "Run items as background jobs and return job ids immediately (default: host configuration)"
    }
  },
  "required": [
    "context",
    "tasks"
  ]
}

{
  "type": "object",
  "properties": {
    "goal": {
      "type": "string",
      "description": "Investigation goal for this checkpoint"
    }
  }
}

{
  "type": "object",
  "properties": {
    "report": {
      "type": "string",
      "description": "Investigation findings retained after the rewind"
    }
  },
  "required": [
    "report"
  ]
}

{
  "type": "object",
  "properties": {
    "target": {
      "type": "string",
      "description": "Numeric id or range from a context marker, e.g. \"5\" or \"2-6\". Omit to list the hidden-segment index."
    },
    "action": {
      "type": "string",
      "description": "Tier 2 segment management (issue #1379). With a target: \"hide\" folds a dead-weight segment into its expandable marker right now, without waiting for pressure; \"pin\" shields a segment from every hide/compact path; \"unpin\" releases it. Omit to expand the target."
    },
    "query": {
      "type": "string",
      "description": "Search the hidden segments (preview and full content) when you know WHAT you need but not the id. Free — no budget."
    },
    "page": {
      "type": "integer",
      "description": "1-based page for giant segments (default 1)",
      "minimum": 1
    }
  },
  "required": []
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The phrase to search for (keyword, or a regular expression with regex: true). Required in search mode."
    },
    "scope": {
      "type": "string",
      "enum": [
        "branch",
        "tree"
      ],
      "description": "branch (default) searches the active branch only; tree spans forks and abandoned branches too."
    },
    "mode": {
      "type": "string",
      "enum": [
        "search",
        "map"
      ],
      "description": "search (default) finds records; map reports the archive structure (counts, hidden totals, checkpoint tree)."
    },
    "kinds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Only these record types (message, compaction, compact_checkpoint, custom, …). Empty keeps every kind."
    },
    "before": {
      "type": "string",
      "description": "Only records older than this ISO-8601 instant."
    },
    "after": {
      "type": "string",
      "description": "Only records newer than this ISO-8601 instant."
    },
    "regex": {
      "type": "boolean",
      "description": "Match query as a case-insensitive regular expression (default: literal keyword)."
    },
    "maxHits": {
      "type": "integer",
      "description": "Cap on returned pointers (default 40, max 200). A capped scan returns a continuation token."
    },
    "continuation": {
      "type": "integer",
      "description": "The token a previous capped call returned — resumes the scan after the records already examined."
    }
  }
}

content.text:
     * shapes: the Java tools resolve either (explicit parts win over key),
     * the Dart issue family speaks owner/repo/number. For composite keys the
     * parts are parsed FROM THE KEY (the key is authoritative); for bare
     * numbers the configured repository fills in.
     */
    function githubIssueArgs(key) {
        var k = expandKey(key);
        var m = /^([\w.-]+)\/([\w.-]+)#(\d+)$/.exec(k);
        if (m) {
            return { key: k, owner: m[1], repo: m[2], number: parseInt(m[3], 10) };
        }
        var args = { key: k, number: githubIssueNumber(k) };
        if (owner) args.owner = owner;
        if (repo) args.repo = repo;
        return args;
    }

    // ── jira provider (canonical jira_* tools) ────────────────────────────

    function jiraGetTicket(key) {
        return normalizeTicket(jira_get_ticket({ key: key }));
    }

    function jiraSearch(query) {
        return _ticketPage(jira_search_by_jql({ jql: query }), 'issues');
    }

    function jiraPostComment(key, comment) {
        return jira_post_comment({ key: key, comment: comment });
    }

    function jiraGetComments(key) {
        return _commentPage(jira_get_comments({ key: key }), 'comments');
    }

    function jiraMoveToStatus(key, status) {
        return jira_move_to_status({ key: key, statusName: status });
    }

    function jiraAssignTo(key, user) {
        return jira_assign_ticket_to({ key: key, accountId: user });
    }

    function jiraCreateTicket(project, type, title, description) {
        return extractTicketKey(jira_create_ticket_basic({
            project: project,
            issueType: type,
            summary: title,
            description: description
        }));
    }



    // Jira payloads pass through UNCHANGED even when the requested fields omit
    // summary (e.g. fields:['key','status']) — only non-Jira-shaped ones convert.
    function _jiraView(raw) {
        var t = _parseJson(raw);
        if (t && typeof t === 'object' && t.fields && typeof t.fields === 'object'
            && t.fields['System.Title'] === undefined) return t;
        return toIssueView(t);
    }

    function jiraGetIssue(key, fields) {
        var args = { key: key };
        if (fields) args.fields = fields;
        return _jiraView(jira_get_ticket(args));
    }

    function jiraSearchIssues(query, opts) {
        var args = { jql: query };
        if (opts && opts.fields) args.fields = opts.fields;
        if (opts && opts.maxResults) args.maxResults = opts.maxResults;
        return _issueList(jira_search_by_jql(args), 'issues', _jiraView);
    }

    function jiraLinkIssues(sourceKey, targetKey, relationship) {
        return jira_link_issues({ sourceKey: sourceKey, anotherKey: targetKey, relationship: relationship });
    }

    function jiraUpdateField(key, field, value) {
        return jira_update_field({ key: key, field: field, value: value });
    }

    function jiraUpdateDescription(key, description) {
        return jira_update_description({ key: key, description: description });
    }

    function jiraSetPriority(key, priority) {
        return jira_set_priority({ key: key, priority: priority });
    }

    function jiraAttachFile(key, name, filePath, contentType) {
        var args = { ticketKey: key, name: name, filePath: filePath };
        if (contentType) args.contentType = contentType;
        return jira_attach_file_to_ticket(args);
    }

    function jiraFieldCode(project, fieldName) {
        var r = jira_get_field_custom_code({ project: project, fieldName: fieldName });
        if (r && typeof r === 'object' && r.result) r = r.result;
        return typeof r === 'string' ? r : null;
    }

    function jiraCreateWithParent(project, type, title, description, parentKey, extra) {
        var args = { project: project, issueType: type, summary: title, description: description, parentKey: parentKey };
        if (extra && extra.labels) args.labels = extra.labels;
        return extractTicketKey(jira_create_ticket_with_parent(args));
    }

    function jiraCreateWithFields(project, fieldsJson) {
        return extractTicketKey(jira_create_ticket_with_json({ project: project, fieldsJson: fieldsJson }));
    }

    // ── ado provider (canonical ado_* tools) ──────────────────────────────

    function adoGetTicket(key) {
        return normalizeTicket(ado_get_work_item({ id: String(key) }));
    }

    function adoSearch(query) {
        return _ticketPage(ado_search_by_wiql({ wiql: query }), 'value');
    }

    // Adds format:'markdown' only when enabled: the html default sends the exact previous args, so a
    // runtime without the 'format' parameter (older dmtools) keeps working unchanged.
    function withAdoFormat(args) {
        if (adoMarkdown) args.format = 'markdown';
        return args;
    }

    function adoPostComment(key, comment) {
        return ado_add_work_item_comment(withAdoFormat({ id: String(key), comment: comment }));
    }

    function adoGetComments(key) {
        return _commentPage(ado_get_work_item_comments({ id: String(key) }), 'value');
    }

    function adoMoveToStatus(key, status) {
        return ado_move_to_state({ id: String(key), state: status });
    }

    function adoAssignTo(key, user) {
        return ado_assign_work_item({ id: String(key), userEmail: user });
    }

    function adoAddLabel(key, label) {
